using System.Collections.Generic;
using Godot;
using Strata.Core.Content;
using Strata.Core.Content.Defs;

namespace Strata.Game.UI;

/// <summary>
/// 32 px buff, debuff and world-event icons generated by tools/textures/build_ui.py into res://assets/icons/buffs and
/// res://assets/icons/events (named by the def's Icon, else its id; debuffs carry a red frame). Textures are cached per
/// id. A def without an image is warned about once and gets a coloured square with its first letter instead, so the gap
/// stays readable. Pixel art: draw at 32 px or an integral multiple, with <c>TextureFilter = Nearest</c> when scaled.
/// </summary>
public static class StatusIcons
{
    private const int Size = 32;

    // 3x5 capital letters for the fallback squares ('#' = ink, rows split by '/'), A to Z.
    private static readonly string[] Letters =
    {
        ".#./#.#/###/#.#/#.#", "##./#.#/##./#.#/##.", ".##/#../#../#../.##", "##./#.#/#.#/#.#/##.", "###/#../##./#../###",
        "###/#../##./#../#..", ".##/#../#.#/#.#/.##", "#.#/#.#/###/#.#/#.#", "###/.#./.#./.#./###", "..#/..#/..#/#.#/.#.",
        "#.#/#.#/##./#.#/#.#", "#../#../#../#../###", "#.#/###/###/#.#/#.#", "##./#.#/#.#/#.#/#.#", ".#./#.#/#.#/#.#/.#.",
        "##./#.#/##./#../#..", ".#./#.#/#.#/##./.##", "##./#.#/##./#.#/#.#", ".##/#../.#./..#/##.", "###/.#./.#./.#./.#.",
        "#.#/#.#/#.#/#.#/###", "#.#/#.#/#.#/#.#/.#.", "#.#/#.#/###/###/#.#", "#.#/#.#/.#./#.#/#.#", "#.#/#.#/.#./.#./.#.",
        "###/..#/.#./#../###",
    };

    private static readonly Dictionary<string, Texture2D> Buffs = new();
    private static readonly Dictionary<string, Texture2D> Events = new();
    private static readonly HashSet<Texture2D> Fallbacks = new();

    /// <summary>Icons asked for that have no image, each counted (and warned about) once.</summary>
    public static int MissingCount { get; private set; }

    public static Texture2D Get(BuffDef def)
    {
        if (!Buffs.TryGetValue(def.Id, out var tex))
            Buffs[def.Id] = tex = Load(AssetPaths.BuffIcon(def), def, def.Color, def.Debuff);
        return tex;
    }

    public static Texture2D Get(EventDef def)
    {
        if (!Events.TryGetValue(def.Id, out var tex))
            Events[def.Id] = tex = Load(AssetPaths.EventIcon(def), def, def.SkyTint ?? "#5a6a9a", false);
        return tex;
    }

    /// <summary>True for the generated letter squares that stand in for a missing image.</summary>
    public static bool IsFallback(Texture2D texture) => Fallbacks.Contains(texture);

    /// <summary>Loads every buff icon and every invasion (kill goal) icon, so showing one never waits on the disk.</summary>
    public static void Preload(ContentDatabase content)
    {
        foreach (var buff in content.Buffs.All) Get(buff);
        foreach (var ev in content.Events.All)
            if (ev.KillGoal > 0) Get(ev);
    }

    private static Texture2D Load(string assetPath, ContentDef def, string color, bool debuff)
    {
        var path = "res://" + assetPath;
        if (ResourceLoader.Exists(path)) return GD.Load<Texture2D>(path);
        GD.PushWarning($"Missing icon for {def} ({path}); add a recipe to tools/textures/ and run build_ui.py.");
        MissingCount++;
        var tex = Fallback(def.DisplayName, Color.FromHtml(color), debuff);
        Fallbacks.Add(tex);
        return tex;
    }

    private static Texture2D Fallback(string name, Color color, bool debuff)
    {
        var img = Image.CreateEmpty(Size, Size, false, Image.Format.Rgba8);
        img.Fill(new Color(0.1f, 0.06f, 0.125f));
        int frame = debuff ? 3 : 1;
        if (debuff) img.FillRect(new Rect2I(1, 1, Size - 2, Size - 2), new Color(0.85f, 0.15f, 0.2f));
        img.FillRect(new Rect2I(frame, frame, Size - 2 * frame, Size - 2 * frame), color.Darkened(0.55f));
        char first = name.Length > 0 ? char.ToUpperInvariant(name[0]) : '?';
        if (first is >= 'A' and <= 'Z')
        {
            var rows = Letters[first - 'A'].Split('/');
            for (int y = 0; y < rows.Length; y++)
                for (int x = 0; x < 3; x++)
                    if (rows[y][x] == '#') img.FillRect(new Rect2I(10 + x * 4, 6 + y * 4, 4, 4), Colors.White);
        }
        return ImageTexture.CreateFromImage(img);
    }
}
